	"confirmado_em" timestamp with time zone,
	"cancelado_em" timestamp with time zone,
	"ultimo_aviso_em" timestamp with time zone,
	"expira_em" date,
	"criado_em" timestamp with time zone NOT NULL,
	CONSTRAINT "ck_aviso_interesse_tipo" CHECK ("aviso_interesse"."tipo" IN ('TREINAMENTO','SETOR','QUALQUER')),
	CONSTRAINT "ck_aviso_interesse_treinamento" CHECK (("aviso_interesse"."tipo" = 'TREINAMENTO') = ("aviso_interesse"."treinamento_id" IS NOT NULL)),
	CONSTRAINT "ck_aviso_interesse_unidade" CHECK (("aviso_interesse"."tipo" = 'SETOR') = ("aviso_interesse"."unidade_id" IS NOT NULL))
);
